// a different material per face direction, blended sharply at the edges (edge: how sharply):
// -x the base colour, +x a metal, the y faces and the z faces a colour each, at the base roughness
let xmin = makeDiffuse(m.baseColor, m.roughness);
let xmax = makeMetal(xPlus, metalRough);
let ymin = makeDiffuse(yFaces, m.roughness);
let ymax = makeDiffuse(yFaces, m.roughness);
let zmin = makeDiffuse(zFaces, m.roughness);
let zmax = makeDiffuse(zFaces, m.roughness);
let e = 1.0 / edge;
let nn = normalize(n);
let wxmin = pow(clamp(-nn.x, 0.0, 1.0), e); let wxmax = pow(clamp(nn.x, 0.0, 1.0), e);
let wymin = pow(clamp(-nn.y, 0.0, 1.0), e); let wymax = pow(clamp(nn.y, 0.0, 1.0), e);
let wzmin = pow(clamp(-nn.z, 0.0, 1.0), e); let wzmax = pow(clamp(nn.z, 0.0, 1.0), e);
let wsum = wxmin + wxmax + wymin + wymax + wzmin + wzmax + 1e-6;
m = xmin;
m = mixMaterials(m, xmax, wxmax / wsum);
m = mixMaterials(m, ymin, wymin / wsum);
m = mixMaterials(m, ymax, wymax / wsum);
m = mixMaterials(m, zmin, wzmin / wsum);
m = mixMaterials(m, zmax, wzmax / wsum);

